{
  "unitCode": "PRG-T00-C02",
  "unitTitle": "JavaScript & TypeScript Baseline",
  "description": "Empirical reasoning schemas and archetypes for baseline JavaScript runtime mechanics and TypeScript type safety (U01 to U07).",
  "archetypes": [
    {
      "archetypeKey": "prg-c02-primitive-coercion-guard",
      "level": 1,
      "archetype": "problem-solving",
      "name": "Defensive Primitive Sanitization & Coercion Guard",
      "competencies": [
        "type-coercion",
        "primitive-semantics",
        "defensive-programming"
      ],
      "coreConcept": "Distinguishing primitive types from reference values, enforcing strict equality, and handling nullish values (null/undefined) safely without overwriting legitimate falsy values (0, false, empty string).",
      "mentalModel": [
        "1. Identify whether incoming properties are primitive values (number, string, boolean) or missing (null, undefined).",
        "2. Use strict equality (===) and nullish coalescing (??) instead of logical OR (||) to preserve legitimate 0 or false values.",
        "3. Return sanitized data transfer object conforming to the schema specification."
      ],
      "governingInvariant": "sanitizedValue = (inputVal !== null && inputVal !== undefined) ? inputVal : defaultValue",
      "cognitiveTraps": [
        {
          "trapTag": "falsy-numeric-zero-overwrite",
          "name": "Falsy Zero Value Overwrite",
          "description": "Using 'val || defaultVal' overwrites valid 0 or empty string with default values.",
          "reproducer": "Pass { timeoutSec: 0 }; with || default of 30, it incorrectly yields 30 instead of 0."
        },
        {
          "trapTag": "loose-equality-type-coercion",
          "name": "Loose Equality Implicit Coercion",
          "description": "Comparing with '==' causes unintended coercion between false, 0, and empty strings.",
          "reproducer": "Comparing '' == 0 returns true, bypassing empty string validation."
        },
        {
          "trapTag": "truthiness-conflation",
          "name": "Truthiness Conflating Valid Falsy Values",
          "description": "Checking '!val' treats legitimate 0, false, or '' the same as null or undefined.",
          "reproducer": "Pass port = 0 to hasValidPort; '!port' rejects 0 instead of distinguishing missing vs zero."
        }
      ],
      "realWorldDomains": [
        {
          "domain": "api_config_sanitizer",
          "description": "Sanitizing environment variable overrides for microservice configuration."
        },
        {
          "domain": "form_input_normalizer",
          "description": "Normalizing user settings where 0 or false are valid operational thresholds."
        }
      ],
      "usedContexts": [
        "api_config_sanitizer",
        "battery_indicator",
        "job_queue_settings",
        "inventory_import",
        "user_profile_header"
      ],
      "qualityChecks": [
        {
          "id": "QC-coercion-explicit-nullish-intent",
          "check": "Missing-value guards and defaults distinguish `null`/`undefined` from legitimate falsy values (`0`, `false`, `''`) by structure rather than truthy/falsy coercion.",
          "why": "Truthy/falsy coercion silently drops valid `0`, `false`, or `''` values on untested branches.",
          "severity": "must",
          "accepted": ["val ?? fallback", "val !== null && val !== undefined", "typeof val === 'number' && Number.isFinite(val)"],
          "knownBad": {
            "code": "function getTimeout(cfg) {\n  return cfg.timeoutSec || 30;\n}",
            "caughtBy": "review"
          }
        },
        {
          "id": "QC-coercion-pure-output",
          "check": "Sanitization constructs an explicit output object with only the intended schema fields rather than forwarding unvalidated properties from the input.",
          "why": "Spreading raw input objects leaks unexpected or unvalidated fields downstream.",
          "severity": "should",
          "knownBad": {
            "code": "function sanitizeConfig(raw) {\n  return { ...raw, timeoutSec: raw.timeoutSec ?? 30 };\n}",
            "caughtBy": "review"
          }
        }
      ]
    },
    {
      "archetypeKey": "prg-c02-lexical-closure-factory",
      "level": 2,
      "archetype": "problem-solving",
      "name": "Encapsulated Lexical Scope & Closure State Factory",
      "competencies": [
        "closures",
        "lexical-scope",
        "encapsulation"
      ],
      "coreConcept": "Creating private state enclosed within execution context boundaries, exposing controlled accessors without leaking internal data structures.",
      "mentalModel": [
        "1. Initialize private state variables inside the outer factory function frame.",
        "2. Return an object interface whose methods form closures over the private state.",
        "3. Ensure external mutation cannot compromise internal state references."
      ],
      "governingInvariant": "privateState accessible exclusively through returned accessor functions; outer lexical frame retained in heap",
      "cognitiveTraps": [
        {
          "trapTag": "closure-shared-reference-leak",
          "name": "Internal Reference Escape",
          "description": "Returning a direct reference to an internal mutable array or object allows external mutation bypassing encapsulation.",
          "reproducer": "Call state.getAll(); mutate returned array; internal registry is corrupted without calling add()."
        }
      ],
      "realWorldDomains": [
        {
          "domain": "metrics_counter_registry",
          "description": "Thread-safe event counter tracking request latency buckets and hit counts."
        },
        {
          "domain": "auth_token_vault",
          "description": "In-memory token vault holding ephemeral credentials with controlled expiration."
        }
      ],
      "usedContexts": [
        "metrics_counter_registry"
      ],
      "qualityChecks": [
        {
          "id": "QC-closure-no-ref-escape",
          "check": "No reference to internal mutable state escapes the factory through any accessor or return value.",
          "why": "Returning a live internal reference lets callers mutate private closure state outside the factory API.",
          "severity": "must",
          "accepted": ["[...items]", "items.slice()", "structuredClone(items)", "Object.freeze({ ...state })"],
          "knownBad": {
            "code": "function createRegistry() {\n  const items = [];\n  return {\n    add(item) { items.push(item); },\n    getAll() { return items; }\n  };\n}",
            "caughtBy": "review"
          }
        },
        {
          "id": "QC-closure-private-state",
          "check": "Mutable state lives in lexical bindings inside the factory closure rather than as properties on the returned object.",
          "why": "Storing state on the returned object exposes it to direct external reassignment.",
          "severity": "must",
          "knownBad": {
            "code": "function createCounter() {\n  return {\n    count: 0,\n    inc() { this.count += 1; }\n  };\n}",
            "caughtBy": "review"
          }
        },
        {
          "id": "QC-closure-minimal-api",
          "check": "The returned interface exposes only the intended domain operations, without leaking internal helpers or raw state setters.",
          "why": "Exposing internal mutators breaks the factory's encapsulation boundary.",
          "severity": "should",
          "knownBad": {
            "code": "function createCounter() {\n  let count = 0;\n  return {\n    inc() { count += 1; },\n    get() { return count; },\n    _setRaw(v) { count = v; }\n  };\n}",
            "caughtBy": "review"
          }
        }
      ]
    },
    {
      "archetypeKey": "prg-c02-immutable-array-pipeline",
      "level": 2,
      "archetype": "problem-solving",
      "name": "Immutable Collection Transformation Pipeline",
      "competencies": [
        "array-transformations",
        "immutability",
        "functional-programming"
      ],
      "coreConcept": "Processing and summarizing datasets using pure transformation pipelines (map, filter, reduce) without mutating input collections.",
      "mentalModel": [
        "1. Filter input records by required business status or timestamp range.",
        "2. Map/transform matching records into normalized reporting schemas.",
        "3. Reduce into structured aggregations (grouping by key, summing totals, computing percentiles)."
      ],
      "governingInvariant": "outputCollection = reduce(filter(map(inputCollection))); inputCollection deeply unchanged",
      "cognitiveTraps": [
        {
          "trapTag": "in-place-array-mutation",
          "name": "In-Place Array Sort Mutation",
          "description": "Calling Array.prototype.sort() directly on input array mutates the original order unexpectedly.",
          "reproducer": "Call sortOrders(orders); check original orders array order; order was permanently altered."
        },
        {
          "trapTag": "reduce-missing-initial-value",
          "name": "Reduce Without Initial Accumulator",
          "description": "Calling reduce() without an explicit initial accumulator throws TypeError on empty arrays and reuses the first element.",
          "reproducer": "Call sumTotals([]); without an initial value, reduce throws TypeError."
        }
      ],
      "realWorldDomains": [
        {
          "domain": "ecommerce_order_revenue_analyzer",
          "description": "Aggregating daily settlement revenue by category with tax breakdowns."
        },
        {
          "domain": "audit_log_telemetry_aggregator",
          "description": "Summarizing microservice error counts grouped by HTTP response code."
        }
      ],
      "usedContexts": [
        "ecommerce_order_revenue_analyzer"
      ],
      "qualityChecks": [
        {
          "id": "QC-pipeline-pure-stages",
          "check": "Transformation stages derive new collections without mutating caller-owned arrays or intermediate elements.",
          "why": "In-place array methods such as `.sort()` or `.reverse()` corrupt the caller's ordering.",
          "severity": "must",
          "accepted": ["[...arr].sort(...)", "arr.toSorted(...)", "arr.slice().sort(...)"],
          "knownBad": {
            "code": "function sortOrders(orders) {\n  return orders.sort((a, b) => a.total - b.total);\n}",
            "caughtBy": "review"
          }
        },
        {
          "id": "QC-pipeline-composable-steps",
          "check": "Filtering, projection, and aggregation are structured as distinct, readable stages rather than a single monolithic loop or reducer mixing all three.",
          "why": "Separating pipeline stages keeps each transformation easy to reason about, test, and extend.",
          "severity": "should",
          "knownBad": {
            "code": "function summarize(orders) {\n  const out = {};\n  for (const o of orders) {\n    if (o.paid) out[o.cat] = (out[o.cat] ?? 0) + o.total * 1.07;\n  }\n  return out;\n}",
            "caughtBy": "review"
          }
        }
      ]
    },
    {
      "archetypeKey": "prg-c02-event-delegation-dispatcher",
      "level": 3,
      "archetype": "debugging",
      "name": "DOM Event Delegation & Propagation Controller",
      "competencies": [
        "dom-events",
        "event-delegation",
        "debugging"
      ],
      "coreConcept": "Managing dynamic UI interactions via parent delegation, accounting for event bubbling from nested child elements (e.g. icons, spans inside buttons), and preventing event propagation issues.",
      "mentalModel": [
        "1. Attach a single listener to the container element rather than each child row.",
        "2. On event trigger, traverse upward using event.target.closest(selector) to match the interactive boundary.",
        "3. Ensure clicks on nested children (icons, bold tags) trigger the correct handler with the parent dataset attributes."
      ],
      "governingInvariant": "delegatedTarget = event.target.closest('[data-action]'); handler executed with target dataset attributes",
      "cognitiveTraps": [
        {
          "trapTag": "nested-target-traversal-bug",
          "name": "Direct Target Assumption on Nested Elements",
          "description": "Inspecting event.target.dataset directly instead of event.target.closest('[data-action]') fails when clicking inner <span> or <i>.",
          "reproducer": "Simulate click with event.target = <span> nested inside <button data-action='delete'>; target.dataset is empty."
        },
        {
          "trapTag": "non-interactive-target-null-deref",
          "name": "Null Dereference on Non-Matching Container Click",
          "description": "Dereferencing the matched action element without guarding against null throws when clicking non-interactive background areas.",
          "reproducer": "Click container padding outside any [data-action] element; handler throws TypeError."
        }
      ],
      "realWorldDomains": [
        {
          "domain": "virtualized_data_table_actions",
          "description": "Handling row action buttons (edit, delete, view) in high-throughput virtualized data tables."
        },
        {
          "domain": "dynamic_kanban_board",
          "description": "Managing interactive task card interactions across dynamic columns."
        }
      ],
      "usedContexts": [],
      "qualityChecks": [
        {
          "id": "QC-delegation-ancestor-resolution",
          "check": "Delegated event handlers resolve the interactive boundary upward from `event.target` and guard against non-matching clicks before reading attributes.",
          "why": "Reading `event.target` directly misses nested children (`<span>`, icons), and unguarded lookups crash on container clicks.",
          "severity": "must",
          "accepted": ["event.target.closest(selector)", "parent-walking loop with element.matches(selector)"],
          "knownBad": {
            "code": "function handleClick(event, onAction) {\n  const action = event.target.dataset.action;\n  if (action) onAction(action);\n}",
            "caughtBy": "review"
          }
        },
        {
          "id": "QC-delegation-dispatch-separation",
          "check": "DOM target lookup is separated from action execution so handlers do not couple DOM traversal to business state updates.",
          "why": "Decoupling target resolution from action dispatch makes the business handler testable without DOM events.",
          "severity": "should",
          "knownBad": {
            "code": "function handleClick(event, store) {\n  const btn = event.target.closest('[data-action]');\n  if (!btn) return;\n  if (btn.dataset.action === 'delete') store.items = store.items.filter((x) => x.id !== btn.dataset.id);\n}",
            "caughtBy": "review"
          }
        }
      ]
    },
    {
      "archetypeKey": "prg-c02-async-promise-combinator",
      "level": 3,
      "archetype": "problem-solving",
      "name": "Resilient Async Microtask & Promise Combinator",
      "competencies": [
        "async-await",
        "promises",
        "concurrency"
      ],
      "coreConcept": "Orchestrating concurrent asynchronous operations with partial failure tolerance, microtask coordination, and deterministic timeout aborts.",
      "mentalModel": [
        "1. Accept an array of asynchronous tasks and execute them concurrently.",
        "2. Isolate failures so that individual task rejections do not abort surviving tasks.",
        "3. Return structured settlement results partitioned into fulfilled values and rejected errors."
      ],
      "governingInvariant": "results.length === tasks.length; all promises settled before resolving combinator",
      "cognitiveTraps": [
        {
          "trapTag": "unhandled-rejection-fast-fail",
          "name": "Premature Fast-Fail with Promise.all",
          "description": "Using Promise.all for independent tasks causes a single transient failure to abort all other valid results.",
          "reproducer": "3 tasks run; task 2 fails; results of task 1 and 3 are lost."
        },
        {
          "trapTag": "completion-order-result-drift",
          "name": "Completion-Order Result Array Drift",
          "description": "Pushing resolved values into an array inside .then() reorders results by completion time instead of input order.",
          "reproducer": "Task 0 takes 30ms, task 1 takes 5ms; output has task 1's result at index 0."
        }
      ],
      "realWorldDomains": [
        {
          "domain": "microservice_health_aggregator",
          "description": "Aggregating upstream service dependency health checks with per-service latency."
        },
        {
          "domain": "parallel_asset_preloader",
          "description": "Preloading critical UI assets in parallel with graceful fallbacks."
        }
      ],
      "usedContexts": [
        "microservice_health_aggregator"
      ],
      "qualityChecks": [
        {
          "id": "QC-async-isolated-settlement",
          "check": "When partial failure tolerance is required, each concurrent task's rejection is isolated so one failure does not abort or drop sibling results.",
          "why": "Unisolated rejections discard valid results from concurrent sibling tasks.",
          "severity": "must",
          "accepted": ["Promise.allSettled(...)", "per-task async wrapper with try/catch returning { status, value | reason }"],
          "knownBad": {
            "code": "async function runAll(tasks) {\n  return Promise.all(tasks.map((task) => task()));\n}",
            "caughtBy": "review"
          }
        },
        {
          "id": "QC-async-no-fire-and-forget",
          "check": "Every spawned promise is awaited or returned in the combinator's settlement chain, with no detached fire-and-forget async work.",
          "why": "Unawaited async calls cause unhandled rejections and return before work completes.",
          "severity": "must",
          "knownBad": {
            "code": "async function runAll(tasks) {\n  const out = [];\n  tasks.forEach((t) => { t().then((v) => out.push(v)); });\n  return out;\n}",
            "caughtBy": "review"
          }
        }
      ]
    },
    {
      "archetypeKey": "prg-c02-discriminated-union-narrowing",
      "level": 4,
      "archetype": "problem-solving",
      "name": "Discriminated Union & State Machine Reducer",
      "competencies": [
        "typescript",
        "type-narrowing",
        "state-machine"
      ],
      "coreConcept": "Implementing strict runtime and compile-time state transitions using discriminated union action patterns and type narrowing guards, enforcing exhaustive coverage without unhandled branches.",
      "mentalModel": [
        "1. Define distinct states and event actions characterized by a common discriminant property (e.g. 'type' or 'status').",
        "2. In the transition reducer, narrow action payload types based on the discriminant.",
        "3. Reject invalid state-to-state transitions with descriptive domain errors, guaranteeing state consistency."
      ],
      "governingInvariant": "newState = transition(currentState, action); invalid transitions throw InvalidStateTransitionError",
      "cognitiveTraps": [
        {
          "trapTag": "unhandled-state-transition-fallthrough",
          "name": "State Mutation on Invalid Transition",
          "description": "Permitting transition actions from incompatible states (e.g. CANCELLED -> SHIPPED) corrupts domain state integrity.",
          "reproducer": "Dispatch PAY event on an already REFUNDED order; status changes to COMPLETED."
        }
      ],
      "realWorldDomains": [
        {
          "domain": "payment_checkout_state_machine",
          "description": "Managing e-commerce payment checkout flow (INITIAL -> AUTHORIZED -> CAPTURED / VOIDED)."
        },
        {
          "domain": "iot_firmware_ota_updater",
          "description": "Enforcing device firmware update lifecycle (IDLE -> DOWNLOADING -> VERIFYING -> FLASHING)."
        }
      ],
      "usedContexts": [
        "payment_checkout_state_machine"
      ],
      "qualityChecks": [
        {
          "id": "QC-union-pure-next-state",
          "check": "State transitions return a new state object instead of mutating the current state in place.",
          "why": "Mutating the current state object breaks reducer predictability and corrupts prior snapshots.",
          "severity": "must",
          "knownBad": {
            "code": "function transition(state, nextStatus) {\n  state.status = nextStatus;\n  return state;\n}",
            "caughtBy": "lint:no-param-reassign"
          }
        },
        {
          "id": "QC-union-exhaustive-switch",
          "check": "Switch or branch chains over a discriminated union include a `default` branch that throws on unknown discriminants.",
          "why": "A missing `default` branch lets newly added action types fall through silently.",
          "severity": "should",
          "knownBad": {
            "code": "function handleAction(action) {\n  switch (action.type) {\n    case 'ADD': return 1;\n    case 'SUB': return -1;\n  }\n  return 0;\n}",
            "caughtBy": "review"
          }
        },
        {
          "id": "QC-union-centralized-transitions",
          "check": "State transitions are defined in one place (a transition table or single reducer) rather than scattered across ad-hoc conditionals.",
          "why": "Scattered transition logic makes illegal state edges easy to miss when adding new actions.",
          "severity": "should",
          "knownBad": {
            "code": "function applyEvent(order, event) {\n  if (event.type === 'SHIP') {\n    if (order.status === 'PAID') return { status: 'SHIPPED' };\n  }\n  if (order.status === 'DRAFT' && event.type === 'PAY') return { status: 'PAID' };\n  return order;\n}",
            "caughtBy": "review"
          }
        }
      ]
    },
    {
      "archetypeKey": "prg-c02-reproducible-defect-isolation",
      "level": 2,
      "archetype": "debugging",
      "name": "Diagnostic Debugging & Minimal Reproducer Isolation",
      "competencies": [
        "debugging",
        "test-driven-investigation",
        "code-comprehension"
      ],
      "coreConcept": "Locating and remediating subtle logical bugs and boundary defects in existing code guided by reproducer test suites without causing regressions.",
      "mentalModel": [
        "1. Run test suite to observe exact assertion failure and reproducer input.",
        "2. Trace variable state changes step-by-step through the defective execution path.",
        "3. Apply targeted remediation preserving external function signature and existing behavior."
      ],
      "governingInvariant": "failing reproducer test turns Green; all existing baseline tests remain Green",
      "cognitiveTraps": [
        {
          "trapTag": "superficial-patch-regression",
          "name": "Special-Case Patching Instead of Root-Cause Fix",
          "description": "Adding an ad-hoc if statement for the specific test case rather than fixing the underlying logical equation.",
          "reproducer": "Add 'if (x === 42) return true;' passing test 1 but failing boundary test with x = 43."
        },
        {
          "trapTag": "signature-contract-break",
          "name": "Breaking Exported Function Signature",
          "description": "Changing the exported function name, parameter order, or return shape breaks existing baseline callers.",
          "reproducer": "Add a required second parameter without a default; baseline single-arg callers throw or fail."
        }
      ],
      "realWorldDomains": [
        {
          "domain": "query_string_url_codec",
          "description": "Fixing URL query string serializer for repeated keys and special character encoding."
        },
        {
          "domain": "nested_property_path_accessor",
          "description": "Fixing deep object path getter ('a.b.c') when encountering null or intermediate primitives."
        }
      ],
      "usedContexts": [],
      "qualityChecks": [
        {
          "id": "QC-debug-no-special-case-patch",
          "check": "The fix addresses the underlying condition or invariant rather than hardcoding an `if` branch for a specific test input.",
          "why": "Special-casing a single reproducer input leaves the root bug intact for all other boundary values.",
          "severity": "must",
          "knownBad": {
            "code": "function getPath(obj, path) {\n  if (path === 'a.b.c') return undefined;\n  return path.split('.').reduce((acc, k) => acc[k], obj);\n}",
            "caughtBy": "review"
          }
        },
        {
          "id": "QC-debug-minimal-diff",
          "check": "The fix is localized to the defective logic without unrelated rewrites or leftover workaround branches.",
          "why": "Broad unrequested rewrites in a bugfix introduce new regressions and obscure the root cause.",
          "severity": "should",
          "knownBad": {
            "code": "function getPath(obj, path) {\n  if (!obj) return undefined;\n  if (path === '') return obj;\n  const parts = path.split('.');\n  let cur = obj;\n  for (const p of parts) {\n    if (cur == null) return undefined;\n    cur = cur[p];\n  }\n  return cur;\n}",
            "caughtBy": "review"
          }
        }
      ]
    },
    {
      "archetypeKey": "prg-c02-function-parameters-basics",
      "level": 1,
      "archetype": "problem-solving",
      "name": "Function Parameters: Defaults, Rest Arguments & Numeric Rounding",
      "competencies": [
        "function-signatures",
        "default-parameters",
        "rest-parameters"
      ],
      "coreConcept": "A function signature controls how missing and variable-length arguments arrive: default parameters apply only when an argument is undefined, rest parameters collect any number of trailing arguments into an array, and money values must be rounded explicitly.",
      "mentalModel": [
        "1. Decide which parameters are required, which have defaults, and which are variadic.",
        "2. Use a default parameter (rate = 0.1) instead of `rate || 0.1`, so an explicit 0 is respected.",
        "3. Collect variadic inputs with a rest parameter (...items) and reduce them with an explicit initial value.",
        "4. Round the final number once, at the end, to the required decimal places and return a number, not a string."
      ],
      "governingInvariant": "f(a) === f(a, defaultValue) && f(a, 0) applies 0; restArgs.reduce(sum, 0) === 0 when no arguments are passed",
      "cognitiveTraps": [
        {
          "trapTag": "falsy-default-overwrite",
          "name": "Falsy Argument Replaced by Default",
          "description": "Using `arg || default` replaces a deliberate 0 with the default value.",
          "reproducer": "applyDiscount(50, 0) returns 45 instead of 50."
        },
        {
          "trapTag": "reduce-without-initial-value",
          "name": "Reduce Without Initial Value",
          "description": "Calling reduce on an empty rest array without an initial value throws a TypeError.",
          "reproducer": "sumInvoiceTotal(0.07) throws instead of returning 0."
        },
        {
          "trapTag": "tofixed-returns-string",
          "name": "toFixed Returns a String",
          "description": "Returning `value.toFixed(2)` yields a string, so strict equality with a number fails.",
          "reproducer": "applyDiscount(19.99) === 17.99 is false because the result is '17.99'."
        }
      ],
      "realWorldDomains": [
        {
          "domain": "checkout_discount",
          "description": "Applying optional promotional rates at checkout."
        },
        {
          "domain": "invoice_totals",
          "description": "Summing a variable number of invoice lines with tax."
        }
      ],
      "usedContexts": [
        "checkout_discount",
        "invoice_totals"
      ],
      "qualityChecks": [
        {
          "id": "QC-params-explicit-signature",
          "check": "Optional defaults and variadic inputs are expressed cleanly in the function signature or explicit nullish guards rather than mutating `arguments` or using falsy `||` fallbacks.",
          "why": "Falsy `||` fallbacks drop explicit `0` or `false` arguments, and `arguments` obscures the function's contract.",
          "severity": "must",
          "accepted": ["function f(a, rate = 0.1, ...items)", "const r = rate ?? 0.1"],
          "knownBad": {
            "code": "function applyDiscount(price, rate) {\n  const r = rate || 0.1;\n  return price * (1 - r);\n}",
            "caughtBy": "review"
          }
        },
        {
          "id": "QC-params-round-at-boundary",
          "check": "Numeric rounding is applied once at the output boundary as a numeric value, keeping intermediate calculations unrounded.",
